1232: const TTT_LINES=[[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]];
1233: const TTT = {
1234:   chan:null, state:null,
1235:   async open(body){
1236:     this.chan = new GameChannel('ttt');
1237:     let st = await this.chan.load();
1238:     if(!st) st = {board:Array(9).fill(null), turn:'user1', winner:null, line:null, scores:{user1:0,user2:0}};
1239:     this.state = st;
1240:     this.chan.listen(p=>{ if(p.type==='sync'){ this.state=p.state; this.render(); } });
1241:     this.render();
1242:   },
1243:   close(){ if(this.chan) this.chan.close(); },
1244:   sync(){ this.chan.send({type:'sync',state:this.state}); this.chan.persist(this.state); },
1245:   mySymbol(){ return ID.role==='user1' ? 'X' : 'O'; },
1246:   play(i){
1247:     if(this.state.winner || this.state.board[i] || this.state.turn!==ID.role) return;
1248:     this.state.board[i]=this.mySymbol();
1249:     const win=this.checkWin();
1250:     if(win){
1251:       this.state.winner=ID.role; this.state.line=win;
1252:       this.state.scores[ID.role]=(this.state.scores[ID.role]||0)+1;
1253:       GameCore.addXP(8); GameCore.addCoins(5); GameCore.addWin(); Snd.success(); TwinCards.done('ttt');
1254:       setTimeout(()=>showReward('🏆','You won this round!',['+8 XP','+5 🪙']),300);
1255:     } else if(this.state.board.every(c=>c)){
1256:       this.state.winner='draw'; Snd.tap(); TwinCards.done('ttt');
1257:     } else {
1258:       this.state.turn = this.state.turn==='user1'?'user2':'user1';
1259:       Snd.place();
1260:     }
1261:     this.sync(); this.render();
1262:   },
1263:   checkWin(){
1264:     const b=this.state.board;
1265:     for(const line of TTT_LINES){ const [a,c,d]=line; if(b[a] && b[a]===b[c] && b[a]===b[d]) return line; }
1266:     return null;
1267:   },
1268:   restart(){ this.state.board=Array(9).fill(null); this.state.turn='user1'; this.state.winner=null; this.state.line=null; this.sync(); this.render(); Snd.tap(); },
1269:   render(){
1270:     const body=document.getElementById('goBody'); if(!body) return;
