1275:         <div class="score-pill ${ID.role==='user2'?'mine':''}"><div class="sp-name">${esc(ID.partnerName)} (${ID.role==='user1'?'O':'X'})</div><div class="sp-val">${s.scores.user2||0}</div></div>
1276:       </div>
1277:       <div class="turn-bar ${myTurn?'mine':''}">${s.winner ? (s.winner==='draw'?'🤝 It is a draw!' : (s.winner===ID.role?'🎉 You won!':esc(ID.partnerName)+' won this round')) : (myTurn?'✨ Your turn':esc(ID.partnerName)+' is turn…')}</div>
1278:       <div class="ttt-board">
1279:         ${s.board.map((c,i)=>`<div class="ttt-cell ${c?c.toLowerCase():''} ${!c&&myTurn?'playable':''} ${s.line&&s.line.includes(i)?'win':''}" onclick="TTT.play(${i})">${c||''}</div>`).join('')}
1280:       </div>
1281:       <div style="text-align:center;margin-top:16px">${s.winner?'<button class="btn btn-accent" onclick="TTT.restart()">🔄 Play Again</button>':''}</div>
